def calculate_a_n(N):
    # Memoization table
    memo = {}

    def a(n):
        if n in memo:
            return memo[n]
        if n == 1:
            return 0

        result = 0

        if n % 2 == 0:
            # n is even: a_n = 2*a_{n/2} + n/2
            result = 2 * a(n // 2) + n // 2
        else:
            # n is odd: a_n = a_{(n-1)/2} + a_{(n+1)/2} + (n-1)/2
            n_minus_1_half = (n - 1) // 2
            n_plus_1_half = (n + 1) // 2
            result = a(n_minus_1_half) + a(n_plus_1_half) + (n - 1) // 2

        memo[n] = result
        return result

    return a(N)

N_target = 2025
a_2025 = calculate_a_n(N_target)
print(f"a_{N_target} = {a_2025}")

def calculate_f(n, i, a):
    return a[i-1] + a[n-i-1] + min(i, n-i)

